import { z } from 'zod'

/**
 * End-to-end encryption of live media (docs/decisions/0004-e2ee.md). One MLS group (RFC 9420, ciphersuite 1) per
 * voice/DM call; the API is its Delivery Service (DS) and only external sender, and never holds a group secret.
 * Each sender's media key per epoch = MLS-Exporter(E2EE_MEDIA_LABEL, mediaKeyContext(userId, deviceId), 32).
 *
 * Devices (REST, api.ts):
 *   A device is an Ed25519 identity generated by the client; its MLS credential is BasicCredential(`userId:deviceId`)
 *   and its leaf signature key is the registered `signatureKey`. The server binds a device to the authenticated user
 *   and session: revoking the session (logout, password change, remote revoke) deletes the device and its key packages.
 *   Key packages are public, single-use and consumed atomically (FOR UPDATE SKIP LOCKED). The client keeps their HPKE
 *   private keys in memory only, so registering again (every app start) empties the device's pool.
 *
 * Call flow (gateway, gateway.ts):
 *   1. `e2ee_join` (after POST /voice/join, in parallel with the LiveKit connection). Empty call: E2EE_EPOCH with
 *      `create`, the client creates the group (group id = UTF-8 channelId, epoch 0, external sender = `externalSender`)
 *      and sends `e2ee_group_info`. Otherwise the DS claims one of the device's key packages and sends E2EE_PROPOSALS
 *      (Add) to the members. A user has one leaf per call: joining again (new device, lost state) is Remove + Add.
 *   2. The member at `committerLeaf` commits every pending proposal (`e2ee_commit`, Welcome included for Adds). The DS
 *      checks it against the public tree (OpenMLS PublicGroup: signature, only its own proposals by reference, Welcome
 *      for exactly the added key packages, committer identity unchanged); the first valid commit of an epoch wins and
 *      goes to every member of that epoch as E2EE_COMMIT (the author merges its pending commit), the Welcome only to
 *      the added device (E2EE_WELCOME). Any other commit for that epoch: E2EE_RESYNC_REQUIRED `commit_rejected`.
 *   3. Receivers install the new epoch's keys on E2EE_COMMIT / E2EE_WELCOME. A welcomed device acks
 *      (`e2ee_welcome_ack`); E2EE_EPOCH for the new epoch follows once every added device acked (or after
 *      E2EE_WELCOME_ACK_TIMEOUT_MS): only then do senders switch to the new epoch's key.
 *   4. Leaving voice (LiveKit webhook) and moderation (kick, ban, move, disconnect, lost access) make the DS propose a
 *      Remove at once. No commit within E2EE_COMMIT_TIMEOUT_MS: the next eligible member becomes the committer.
 *   5. Lost or diverged state (failed commit/Welcome, reconnect at another epoch): `e2ee_resync`, the DS re-adds the
 *      device. Re-adding is the only recovery path.
 *
 * The DS can still misbehave (key substitution, ghost members, split groups, denial of service): see
 * docs/security/e2ee-delivery-service.md. Clients take the member list from MLS and show the verification code.
 */

export const E2EE_CIPHERSUITE = 1 // MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519
/** BasicCredential identity of the DS as external sender. */
export const E2EE_DS_IDENTITY = 'alga-ds'
/** MLS-Exporter label of the per-sender media key (LiveKit key provider, keyIndex = epoch % 16). */
export const E2EE_MEDIA_LABEL = 'Alga Media v1'
export const mediaKeyContext = (userId: string, deviceId: string) => `${userId}\0${deviceId}`
/** `userId:deviceId`, the BasicCredential identity of a device. */
export const deviceIdentity = (userId: string, deviceId: string) => `${userId}:${deviceId}`

export const E2EE_MAX_DEVICES_PER_USER = 10
/** Key packages a device may have waiting on the server. */
export const E2EE_MAX_KEY_PACKAGES_PER_DEVICE = 100
export const E2EE_MAX_KEY_PACKAGES_PER_UPLOAD = 50
/** Decoded sizes. A key package is ~290 B; at 99 members a Welcome is ~19 KB and a removal commit ~9 KB. */
export const E2EE_MAX_KEY_PACKAGE_BYTES = 1024
export const E2EE_MAX_COMMIT_BYTES = 16 * 1024
export const E2EE_MAX_WELCOME_BYTES = 32 * 1024
export const E2EE_MAX_GROUP_INFO_BYTES = 32 * 1024
/** Raw size of one e2ee_* gateway frame (other ops stay at 16 KiB). */
export const E2EE_MAX_FRAME_BYTES = 72 * 1024
/** e2ee_* frames per socket per minute, counted apart from the general gateway quota. */
export const E2EE_FRAME_LIMIT = 60
export const E2EE_COMMIT_TIMEOUT_MS = 1000
export const E2EE_WELCOME_ACK_TIMEOUT_MS = 300
/** e2ee_join is allowed before the LiveKit join lands; without a voice state in the channel by then, the leaf is removed. */
export const E2EE_JOIN_GRACE_MS = 15_000

const b64 = (maxBytes: number) => z.string().min(4).max(Math.ceil(maxBytes / 3) * 4).regex(/^[A-Za-z0-9+/]+={0,2}$/, 'base64')

// ---- REST ------------------------------------------------------------------------------------------------------------

/** POST /e2ee/devices. `signatureKey`: raw Ed25519 public key, base64 (32 bytes). */
export const RegisterDeviceBody = z.object({
  deviceId: z.uuid(),
  signatureKey: z.string().regex(/^[A-Za-z0-9+/]{43}=$/, 'base64 of 32 bytes'),
})
export type RegisterDeviceBody = z.infer<typeof RegisterDeviceBody>

/** POST /e2ee/devices/:deviceId/key-packages: MLSMessage(KeyPackage) bytes, base64. */
export const UploadKeyPackagesBody = z.object({
  keyPackages: z.array(b64(E2EE_MAX_KEY_PACKAGE_BYTES)).min(1).max(E2EE_MAX_KEY_PACKAGES_PER_UPLOAD),
})
export type UploadKeyPackagesBody = z.infer<typeof UploadKeyPackagesBody>

export interface E2eeDevice {
  userId: string
  deviceId: string
  signatureKey: string
  /** Key packages waiting on the server (0 right after a registration). */
  keyPackages: number
  createdAt: string
}

export interface KeyPackagesUploaded {
  /** Pool size after the upload. */
  keyPackages: number
}

/** GET /e2ee/users/:userId/key-packages: one key package per device of the user that still has one (consumed). */
export interface ClaimedKeyPackages {
  keyPackages: { deviceId: string; signatureKey: string; keyPackage: string }[]
}

// ---- gateway ---------------------------------------------------------------------------------------------------------

const channelId = z.uuid()
const epoch = z.number().int().min(0).max(Number.MAX_SAFE_INTEGER)

export const E2eeClientFrameSchema = z.discriminatedUnion('op', [
  /** Join intent, or re-announce after a gateway reconnect: `epoch` = the local group's epoch (omit without state). */
  z.object({ op: z.literal('e2ee_join'), channelId, deviceId: z.uuid(), epoch: epoch.optional() }),
  /** Creator only, right after E2EE_EPOCH `create`: GroupInfo (with ratchet tree) of epoch 0. */
  z.object({ op: z.literal('e2ee_group_info'), channelId, groupInfo: b64(E2EE_MAX_GROUP_INFO_BYTES) }),
  /** Commit (PublicMessage) for `epoch` covering pending DS proposals; Welcome when it adds someone. */
  z.object({ op: z.literal('e2ee_commit'), channelId, epoch, commit: b64(E2EE_MAX_COMMIT_BYTES), welcome: b64(E2EE_MAX_WELCOME_BYTES).optional() }),
  /** The Welcome was processed: the device is a member at `epoch`. */
  z.object({ op: z.literal('e2ee_welcome_ack'), channelId, epoch }),
  /** Local state lost or a commit/Welcome failed to apply: remove this user's leaf and re-add the device. */
  z.object({ op: z.literal('e2ee_resync'), channelId, deviceId: z.uuid() }),
])
export type E2eeClientFrame = z.infer<typeof E2eeClientFrameSchema>

export const E2EE_RESYNC_REASONS = [
  /** Your commit was not ordered (another one won, or it failed validation): clear the pending commit, keep state. */
  'commit_rejected',
  /** The device has no key package left: upload some, then send e2ee_join again. */
  'no_key_package',
  /** The DS does not see this device in the group at your epoch: drop the local group, send e2ee_join again. */
  'not_member',
  /** No device of this id registered by this session: POST /e2ee/devices first. */
  'unknown_device',
  /** You may not join this call (no CONNECT, not a recipient, blocked, text channel). Do not retry. */
  'forbidden',
  /** E2EE is off on this server. Do not retry. */
  'unavailable',
] as const
export type E2eeResyncReason = (typeof E2EE_RESYNC_REASONS)[number]

export interface E2eeExternalSender {
  /** Raw Ed25519 public key, base64. */
  publicKey: string
  /** BasicCredential identity (E2EE_DS_IDENTITY). */
  identity: string
}

/** DS-signed external proposals (Add/Remove, MLSMessage base64) for `epoch`, to every member device of that epoch. */
export interface E2eeProposals {
  channelId: string
  epoch: number
  proposals: string[]
  /** Leaf that commits them; the others only queue them. */
  committerLeaf: number
}

/** The commit the DS ordered for `epoch` (first valid one); members move to epoch + 1. Sent to every member of `epoch`. */
export interface E2eeCommit {
  channelId: string
  epoch: number
  commit: string
}

/** Only to the added device: join the group at `epoch`. */
export interface E2eeWelcome {
  channelId: string
  epoch: number
  welcome: string
}

/**
 * The DS's view of the call's epoch. `create`: the call is empty, create the group (group id = UTF-8 channelId) with
 * this external sender and send e2ee_group_info. Otherwise: start sending with this epoch's key, and commit pending
 * proposals if `committerLeaf` is yours (also re-sent when the committer changes or on an e2ee_join at this epoch).
 */
export interface E2eeEpoch {
  channelId: string
  epoch: number
  committerLeaf: number
  create: boolean
  externalSender: E2eeExternalSender
}

export interface E2eeResyncRequired {
  channelId: string
  reason: E2eeResyncReason
}
